import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e3f2fd', stroke: '#1976d2' },
  mask: { fill: '#fff3e0', stroke: '#f97316' },
  kept: { fill: '#e8f5e9', stroke: '#22c55e' },
  output: { fill: '#e8f5e9', stroke: '#4caf50' },
  weight: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  scale: { fill: '#fff8e1', stroke: '#f59e0b' },
  residual: { fill: '#e0f2f1', stroke: '#14b8a6' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 80;
const MAT_W = 260;
const MAT_H = 156;
const SCALAR_SIZE = 80;
const STEP_GAP = 280;
const BOX_TO_ROW = 200;
const SHAPE_GAP = 96;
const SIDE_OFF = 340;
const ARROW_MARGIN = 20;

const GRID_ROWS = 6;
const GRID_COLS = 8;
const CELL = 24;

interface DropoutStep extends StepInfo {}
type DropoutVariant = 'standard' | 'droppath' | 'dropconnect';

function lcg(seed: number): () => number {
  let s = seed;
  return () => { s = (s * 1664525 + 1013904223) & 0x7fffffff; return s / 0x7fffffff; };
}

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowH(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function arrowV(
  g: Gsel, x: number, yFrom: number, yTo: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = yTo >= yFrom ? 1 : -1;
  drawArrow(g as Sel, x, yFrom + dir * margin, x, yTo - dir * margin, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 80
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 7.5 + 48, 320);
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function matrixBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = MAT_W, h = MAT_H,
  dimTop?: string, dimLeft?: string
): void {
  const top = dimTop ?? (sub.includes(',') ? sub.split(',')[1].trim().replace(/\]/, '') : '');
  const left = dimLeft ?? (sub.includes(',') ? sub.split(',')[0].trim().replace(/\[/, '') : '');
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 6, dimTop: top, dimLeft: left,
  });
}

function scalarBlock(g: Gsel, cx: number, cy: number, label: string, sub = '', fill?: string, stroke?: string): void {
  drawMatrixBlock(g as Sel, cx - SCALAR_SIZE / 2, cy - SCALAR_SIZE / 2, {
    width: SCALAR_SIZE, height: SCALAR_SIZE, label, sublabel: sub,
    fill: fill || COLORS.mask.fill, stroke: stroke || COLORS.mask.stroke,
    cols: 1, rows: 1,
  });
}

function opBox(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = text.length * 9 + 24;
  const h = 32;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 12, weight: '700', color });
}

function smallNote(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'start'): void {
  lbl(g, x, y, text, { size: 9, color, anchor, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 32, 180);
  const h = 22;
  g.append('rect')
    .attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color)
    .attr('stroke-width', 0.5).attr('opacity', 0.88);
  lbl(g, cx, cy + 1, text, { size: 9, color, font: 'monospace' });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): DropoutStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawHighlightRow(g: Gsel, cx: number, cy: number, w: number, h: number, row: number, rows: number, color: string): void {
  const cellH = (h - 2) / rows;
  const y = cy - h / 2 + 1 + row * cellH;
  g.append('rect').attr('x', cx - w / 2 + 1).attr('y', y).attr('width', w - 2).attr('height', cellH - 1)
    .attr('fill', color).attr('opacity', 0.25).attr('stroke', color).attr('stroke-width', 1);
}

function drawBinaryMaskGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number, seed: number, rate: number
): { width: number; height: number } {
  const rand = lcg(seed);
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const isDropped = rand() < rate;
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isDropped ? '#fff3e0' : '#e8f5e9').attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, isDropped ? '0' : '1', {
        size: 10, color: isDropped ? '#f97316' : '#22c55e', weight: '600',
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', '#64748b').attr('stroke-width', 1).attr('rx', 2);
  return { width: w, height: h };
}

function drawMaskedMatrix(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  seed: number, rate: number, values: number[]
): void {
  const rand = lcg(seed);
  const dropped: boolean[] = [];
  for (let i = 0; i < rows * cols; i++) dropped.push(rand() < rate);
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const isDropped = dropped[idx];
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isDropped ? '#fef2f2' : '#f0fdf4').attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      const val = values[idx % values.length];
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, isDropped ? '0' : val.toFixed(1), {
        size: 9, color: isDropped ? '#f87171' : '#16a34a',
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', '#64748b').attr('stroke-width', 1).attr('rx', 2);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Standard Dropout renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderStandard(
  g: Gsel, yStart: number, seqLen: number, dModel: number, rate: number, hiRow: number
): { steps: DropoutStep[]; y: number } {
  const steps: DropoutStep[] = [];
  let y = yStart;

  // Step 1: Input Activations
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations',
      `x [${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    matrixBlock(gs, CX, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W, MAT_H, String(dModel), String(seqLen));
    drawHighlightRow(gs, CX, rowY, MAT_W, MAT_H, hiRow, 6, COLORS.input.stroke);
    lbl(gs, CX - MAT_W / 2 - 14, rowY - MAT_H / 2 + (hiRow + 0.5) * (MAT_H / 6), 't', { color: COLORS.input.stroke, anchor: 'end' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 32, `x [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + MAT_H / 2 + 32 + 28,
      `e.g. x[${hiRow}, :] = [1.2, -0.8, 2.1, ...]`, COLORS.input.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Activations',
      `x [${seqLen}, ${dModel}]`,
      'Input activation matrix from the previous layer. Each row is one token position.',
      'step-input', COLORS.input.stroke, COLORS.input.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`]));
    y = rowY + MAT_H / 2 + 32 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Generate Binary Mask
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-mask', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Generate Binary Mask',
      `m ~ Bernoulli(1 - p)`, COLORS.mask.fill, COLORS.mask.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    drawBinaryMaskGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, 42, rate);
    lbl(gs, CX, rowY - (GRID_ROWS * CELL) / 2 - 18, 'm', { size: 13, weight: '700', color: COLORS.mask.stroke });
    smallNote(gs, CX + (GRID_COLS * CELL) / 2 + 12, rowY - 10, `green = kept (1)`, COLORS.kept.stroke);
    smallNote(gs, CX + (GRID_COLS * CELL) / 2 + 12, rowY + 10, `orange = dropped (0)`, COLORS.mask.stroke);

    shapeEq(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28,
      `m [${seqLen}, ${dModel}] ~ Bernoulli(${(1 - rate).toFixed(1)})`, COLORS.mask.stroke);
    sampleNote(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28 + 28,
      `p=${rate} → ~${Math.round(rate * 100)}% zeros`, COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'Mask', 'Generate Binary Mask',
      `m ~ Bernoulli(1 - p)`,
      'Sample a binary mask with the same shape as the input. Each element is independently 1 with probability 1-p.',
      'step-mask', COLORS.mask.stroke, COLORS.mask.fill,
      [`mask = torch.bernoulli(torch.full_like(x, ${1 - rate}))`]));
    y = rowY + (GRID_ROWS * CELL) / 2 + 28 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Apply Mask (element-wise multiply)
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-apply', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Apply Mask',
      `x_d = x ⊙ m`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.7, MAT_H * 0.7);
    opBox(gs, CX, rowY, '⊙', COLORS.mask.stroke);
    drawMaskedMatrix(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, CELL, 42, rate, [1.2, -0.8, 2.1, 0.5, -1.3, 0.9, 1.7, -0.4]);

    arrowH(gs, CX - SIDE_OFF + MAT_W * 0.35, CX - 24, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 24, CX + SIDE_OFF - (GRID_COLS * CELL) / 2, rowY, COLORS.output.stroke);

    smallNote(gs, CX + SIDE_OFF, rowY - (GRID_ROWS * CELL) / 2 - 14, 'x_d = x ⊙ m', COLORS.input.stroke, 'middle');

    shapeEq(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28,
      `x_d = x ⊙ m  [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28 + 28,
      'dropped positions → 0', COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'Apply', 'Apply Mask',
      `x_d = x ⊙ m`,
      'Element-wise multiplication zeros out dropped activations.',
      'step-apply', COLORS.input.stroke, COLORS.input.fill,
      [`x_dropped = x * mask`]));
    y = rowY + (GRID_ROWS * CELL) / 2 + 28 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Inverted Scaling
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-scale', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Inverted Scaling',
      `out = x_d × 1/(1-p)`, COLORS.scale.fill, COLORS.scale.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'x_d', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W, MAT_H);
    opBox(gs, CX, rowY, `× ${1 / (1 - rate) === Math.round(1 / (1 - rate)) ? (1 / (1 - rate)).toFixed(0) : (1 / (1 - rate)).toFixed(2)}`, COLORS.scale.stroke);
    matrixBlock(gs, CX + SIDE_OFF, rowY, 'out', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W, MAT_H);

    const scaleY = rowY - 100;
    scalarBlock(gs, CX + 40, scaleY, `1/(1-p)`, `${(1 / (1 - rate)).toFixed(2)}`, COLORS.scale.fill, COLORS.scale.stroke);

    arrowH(gs, CX - SIDE_OFF + MAT_W / 2, CX - 30, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 30, CX + SIDE_OFF - MAT_W / 2, rowY, COLORS.output.stroke);
    arrowV(gs, CX + 40, scaleY + SCALAR_SIZE / 2, rowY - 16, COLORS.scale.stroke);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 32,
      `out = x_d / (1 - ${rate})`, COLORS.scale.stroke);
    sampleNote(gs, CX, rowY + MAT_H / 2 + 32 + 28,
      `p=${rate} → ×${(1 / (1 - rate)).toFixed(2)} (keeps E[out] = E[x])`, COLORS.scale.stroke);

    steps.push(makeStep(stepId, 'Scale', 'Inverted Scaling',
      `out = x_d / (1-p)`,
      'Scale by 1/(1-p) so the expected value matches the input. This is "inverted dropout".',
      'step-scale', COLORS.scale.stroke, COLORS.scale.fill,
      [`out = x_dropped / (1 - ${rate})`]));
    y = rowY + MAT_H / 2 + 32 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 5: Output
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `out [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX, rowY, 'out', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W, MAT_H, String(dModel), String(seqLen));
    drawHighlightRow(gs, CX, rowY, MAT_W, MAT_H, hiRow, 6, COLORS.output.stroke);
    lbl(gs, CX + MAT_W / 2 + 24, rowY, 'E[out] = E[x]', { size: 11, color: COLORS.muted, anchor: 'start' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 32,
      `out [${seqLen}, ${dModel}]`, COLORS.output.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `out [${seqLen}, ${dModel}]`,
      'Output has the same shape and expected value as input, but with some positions zeroed and others scaled up.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# E[out] = E[x] (inverted dropout preserves expectation)`]));
    y = rowY + MAT_H / 2 + 32 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// DropPath (Stochastic Depth) renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderDropPath(
  g: Gsel, yStart: number, seqLen: number, dModel: number, rate: number, _hiRow: number
): { steps: DropoutStep[]; y: number } {
  const steps: DropoutStep[] = [];
  let y = yStart;

  // Step 1: Input + Residual Branch
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input + Residual Branch',
      `x + f(x)  [${seqLen}, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const branchX = CX - 200;
    const residX = CX + 200;

    matrixBlock(gs, branchX, rowY, 'f(x)', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.85, MAT_H * 0.85);
    smallNote(gs, branchX, rowY - MAT_H * 0.425 - 16, 'main branch (transform)', COLORS.input.stroke, 'middle');

    matrixBlock(gs, residX, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke, MAT_W * 0.85, MAT_H * 0.85);
    smallNote(gs, residX, rowY - MAT_H * 0.425 - 16, 'residual (skip connection)', COLORS.residual.stroke, 'middle');

    const elbowY1 = rowY + MAT_H * 0.425 + 30;
    const elbowY2 = rowY + MAT_H * 0.425 + 50;
    const plusY = elbowY2 + 40;
    opBox(gs, CX, plusY, '+', COLORS.residual.stroke);

    arrowV(gs, branchX, rowY + MAT_H * 0.425, elbowY1, COLORS.input.stroke);
    arrowH(gs, branchX, CX - 24, elbowY1, COLORS.input.stroke);
    arrowV(gs, CX - 12, elbowY1, plusY - 16, COLORS.input.stroke);

    arrowV(gs, residX, rowY + MAT_H * 0.425, elbowY2, COLORS.residual.stroke);
    arrowH(gs, residX, CX + 24, elbowY2, COLORS.residual.stroke);
    arrowV(gs, CX + 12, elbowY2, plusY - 16, COLORS.residual.stroke);

    const outY = plusY + 60;
    matrixBlock(gs, CX, outY, 'x + f(x)', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W, MAT_H * 0.65);
    arrowV(gs, CX, plusY + 16, outY - MAT_H * 0.325, COLORS.output.stroke);

    shapeEq(gs, CX, outY + MAT_H * 0.325 + 32,
      `output = x + f(x)`, COLORS.residual.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input + Residual Branch',
      `x + f(x)`,
      'In residual networks, each block adds its output f(x) to the input x. DropPath can drop the f(x) branch.',
      'step-input', COLORS.residual.stroke, COLORS.residual.fill,
      [`# Standard residual: out = x + f(x)`]));
    y = outY + MAT_H * 0.325 + 32 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Sample Branch-Level Mask
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-mask', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sample Branch Mask',
      `m ~ Bernoulli(1 - p)  (per sample)`, COLORS.mask.fill, COLORS.mask.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    scalarBlock(gs, CX, rowY, 'm', `per sample`, COLORS.mask.fill, COLORS.mask.stroke);
    smallNote(gs, CX, rowY - SCALAR_SIZE / 2 - 20, 'one coin flip per batch sample', COLORS.mask.stroke, 'middle');

    shapeEq(gs, CX, rowY + SCALAR_SIZE / 2 + 32,
      `m ~ Bernoulli(${(1 - rate).toFixed(1)})  scalar per sample`, COLORS.mask.stroke);
    sampleNote(gs, CX, rowY + SCALAR_SIZE / 2 + 32 + 28,
      'NOT per-element — entire branch is kept or dropped', COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'Mask', 'Sample Branch Mask',
      `m ~ Bernoulli(1 - p)`,
      'Unlike standard dropout, DropPath samples ONE mask per batch sample, not per element. The entire residual branch is gated.',
      'step-mask', COLORS.mask.stroke, COLORS.mask.fill,
      [`shape = (B,) + (1,) * (x.ndim - 1)`,
       `mask = torch.bernoulli(torch.full(shape, ${1 - rate}))`]));
    y = rowY + SCALAR_SIZE / 2 + 32 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Gate Residual
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-gate', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Gate Residual',
      `out = x + m · f(x)`, COLORS.residual.fill, COLORS.residual.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const keepX = CX - 220;
    const dropX = CX + 220;
    const caseH = 150;
    const caseW = 320;

    // m=1 case
    gs.append('rect').attr('x', keepX - caseW / 2).attr('y', rowY - caseH / 2).attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#f0fdf4').attr('stroke', COLORS.kept.stroke).attr('stroke-width', 1);
    lbl(gs, keepX, rowY - caseH / 2 + 20, 'm = 1  (branch active)', { size: 12, weight: '700', color: COLORS.kept.stroke });
    lbl(gs, keepX, rowY - 4, 'out = x + f(x)', { size: 11, color: 'var(--text)', font: 'monospace' });
    lbl(gs, keepX, rowY + 20, 'normal residual flow', { size: 9, color: COLORS.muted });
    lbl(gs, keepX, rowY + caseH / 2 - 18, 'f(x) passes through', { size: 9, color: COLORS.kept.stroke });

    // m=0 case
    gs.append('rect').attr('x', dropX - caseW / 2).attr('y', rowY - caseH / 2).attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#fef2f2').attr('stroke', '#f87171').attr('stroke-width', 1);
    lbl(gs, dropX, rowY - caseH / 2 + 20, 'm = 0  (branch dropped)', { size: 12, weight: '700', color: '#ef4444' });
    lbl(gs, dropX, rowY - 4, 'out = x + 0 = x', { size: 11, color: 'var(--text)', font: 'monospace' });
    lbl(gs, dropX, rowY + 20, 'identity — branch skipped', { size: 9, color: COLORS.muted });
    lbl(gs, dropX, rowY + caseH / 2 - 18, 'f(x) zeroed out', { size: 9, color: '#ef4444' });

    shapeEq(gs, CX, rowY + caseH / 2 + 32,
      `out = x + m · f(x)`, COLORS.residual.stroke);
    sampleNote(gs, CX, rowY + caseH / 2 + 32 + 32,
      `p=${rate} → branch dropped ${Math.round(rate * 100)}% of the time`, COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'Gate', 'Gate Residual',
      `out = x + m · f(x)`,
      'When m=1 the branch is active. When m=0 the branch is dropped and the residual passes through unchanged.',
      'step-gate', COLORS.residual.stroke, COLORS.residual.fill,
      [`out = x + mask * f(x) / (1 - ${rate})`]));
    y = rowY + caseH / 2 + 32 + 32 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Training vs Inference
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-mode', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Training vs Inference',
      `train: x + m·f(x)/(1-p)  |  eval: x + f(x)`, COLORS.scale.fill, COLORS.scale.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const trainX = CX - 220;
    const evalX = CX + 220;
    const caseH = 130;
    const caseW = 340;

    gs.append('rect').attr('x', trainX - caseW / 2).attr('y', rowY - caseH / 2).attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#fffbeb').attr('stroke', COLORS.scale.stroke).attr('stroke-width', 1);
    lbl(gs, trainX, rowY - caseH / 2 + 20, 'Training', { size: 12, weight: '700', color: COLORS.scale.stroke });
    lbl(gs, trainX, rowY - 4, 'out = x + m · f(x) / (1-p)', { size: 10, color: 'var(--text)', font: 'monospace' });
    lbl(gs, trainX, rowY + 20, 'scaled like inverted dropout', { size: 9, color: COLORS.muted });

    gs.append('rect').attr('x', evalX - caseW / 2).attr('y', rowY - caseH / 2).attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#f0fdf4').attr('stroke', COLORS.kept.stroke).attr('stroke-width', 1);
    lbl(gs, evalX, rowY - caseH / 2 + 20, 'Inference', { size: 12, weight: '700', color: COLORS.kept.stroke });
    lbl(gs, evalX, rowY - 4, 'out = x + f(x)', { size: 10, color: 'var(--text)', font: 'monospace' });
    lbl(gs, evalX, rowY + 20, 'no dropout — all branches active', { size: 9, color: COLORS.muted });

    shapeEq(gs, CX, rowY + caseH / 2 + 32,
      `DropPath disabled at test time`, COLORS.scale.stroke);

    steps.push(makeStep(stepId, 'Mode', 'Training vs Inference',
      `train vs eval`,
      'Like all dropout variants, DropPath is only active during training. At inference time every branch contributes.',
      'step-mode', COLORS.scale.stroke, COLORS.scale.fill,
      [`if training: out = x + mask * f(x) / (1-p)`,
       `else:       out = x + f(x)`]));
    y = rowY + caseH / 2 + 32 + SHAPE_GAP + STEP_GAP;
  }

  // Step 5: Output
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `out [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX, rowY, 'out', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W, MAT_H, String(dModel), String(seqLen));
    lbl(gs, CX + MAT_W / 2 + 24, rowY, 'used in ResNets / ViT', { size: 11, color: COLORS.muted, anchor: 'start' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 32,
      `out [${seqLen}, ${dModel}]`, COLORS.output.stroke);
    sampleNote(gs, CX, rowY + MAT_H / 2 + 32 + 28,
      'deeper blocks typically use higher drop rates', COLORS.residual.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `out [${seqLen}, ${dModel}]`,
      'Output preserves shape. DropPath acts as a regularizer that encourages the network to not rely on any single residual block.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# Deeper blocks → higher drop rate (e.g. 0→0.2 linearly)`]));
    y = rowY + MAT_H / 2 + 32 + 28 + 22 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// DropConnect renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderDropConnect(
  g: Gsel, yStart: number, seqLen: number, dModel: number, rate: number, _hiRow: number
): { steps: DropoutStep[]; y: number } {
  const steps: DropoutStep[] = [];
  let y = yStart;

  // Step 1: Input + Weight
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input + Weight Matrix',
      `x [${seqLen}, ${dModel}]  ×  W [${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xCX = CX - 240;
    const wCX = CX + 240;

    matrixBlock(gs, xCX, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.85, MAT_H * 0.85);
    matrixBlock(gs, wCX, rowY, 'W', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, MAT_W * 0.85, MAT_H * 0.85);

    smallNote(gs, xCX, rowY - MAT_H * 0.425 - 18, 'input activations', COLORS.input.stroke, 'middle');
    smallNote(gs, wCX, rowY - MAT_H * 0.425 - 18, 'weight matrix', COLORS.weight.stroke, 'middle');

    shapeEq(gs, CX, rowY + MAT_H * 0.425 + 32,
      `x [${seqLen}, ${dModel}],  W [${dModel}, ${dModel}]`, COLORS.weight.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input + Weight Matrix',
      `x × W`,
      'DropConnect masks the weight matrix instead of the activations. We need both x and W.',
      'step-input', COLORS.weight.stroke, COLORS.weight.fill,
      [`x: [${seqLen}, ${dModel}]`, `W: [${dModel}, ${dModel}]`]));
    y = rowY + MAT_H * 0.425 + 32 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Generate Weight Mask
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-mask', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Generate Weight Mask',
      `M ~ Bernoulli(1 - p)  [${dModel}, ${dModel}]`, COLORS.mask.fill, COLORS.mask.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    drawBinaryMaskGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, 99, rate);
    lbl(gs, CX, rowY - (GRID_ROWS * CELL) / 2 - 18, 'M', { size: 13, weight: '700', color: COLORS.mask.stroke });
    smallNote(gs, CX + (GRID_COLS * CELL) / 2 + 12, rowY - 10, `masks weights`, COLORS.mask.stroke);
    smallNote(gs, CX + (GRID_COLS * CELL) / 2 + 12, rowY + 10, `NOT activations`, '#ef4444');

    shapeEq(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28,
      `M [${dModel}, ${dModel}] ~ Bernoulli(${(1 - rate).toFixed(1)})`, COLORS.mask.stroke);
    sampleNote(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28 + 28,
      'same shape as W, not x', COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'Mask', 'Generate Weight Mask',
      `M ~ Bernoulli(1 - p)`,
      'Generate a binary mask with the same shape as the weight matrix. This is the key difference from standard dropout.',
      'step-mask', COLORS.mask.stroke, COLORS.mask.fill,
      [`M = torch.bernoulli(torch.full_like(W, ${1 - rate}))`]));
    y = rowY + (GRID_ROWS * CELL) / 2 + 28 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Mask Weights
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-apply', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Mask Weights',
      `W_d = W ⊙ M`, COLORS.weight.fill, COLORS.weight.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'W', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, MAT_W * 0.8, MAT_H * 0.8);
    opBox(gs, CX, rowY, '⊙', COLORS.mask.stroke);
    drawMaskedMatrix(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, CELL, 99, rate, [0.12, -0.34, 0.56, -0.21, 0.78, -0.45, 0.33, -0.67]);

    arrowH(gs, CX - SIDE_OFF + MAT_W * 0.4, CX - 24, rowY, COLORS.weight.stroke);
    arrowH(gs, CX + 24, CX + SIDE_OFF - (GRID_COLS * CELL) / 2, rowY, COLORS.output.stroke);

    smallNote(gs, CX + SIDE_OFF, rowY - (GRID_ROWS * CELL) / 2 - 14, 'W_d = W ⊙ M', COLORS.weight.stroke, 'middle');

    shapeEq(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28,
      `W_d = W ⊙ M  [${dModel}, ${dModel}]`, COLORS.weight.stroke);
    sampleNote(gs, CX, rowY + (GRID_ROWS * CELL) / 2 + 28 + 28,
      'zeroed weights → no gradient flow', COLORS.mask.stroke);

    steps.push(makeStep(stepId, 'MaskW', 'Mask Weights',
      `W_d = W ⊙ M`,
      'Element-wise multiplication zeros out individual weights. Dropped weights do not participate in forward or backward pass.',
      'step-apply', COLORS.weight.stroke, COLORS.weight.fill,
      [`W_dropped = W * M`]));
    y = rowY + (GRID_ROWS * CELL) / 2 + 28 + 28 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Matrix Multiply
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-matmul', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Matrix Multiply',
      `out = x @ W_d / (1-p)`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.8, MAT_H * 0.8);
    opBox(gs, CX, rowY, '@', COLORS.input.stroke);
    matrixBlock(gs, CX + SIDE_OFF, rowY, 'out', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W * 0.8, MAT_H * 0.8);

    arrowH(gs, CX - SIDE_OFF + MAT_W * 0.4, CX - 24, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 24, CX + SIDE_OFF - MAT_W * 0.4, rowY, COLORS.output.stroke);

    const wY = rowY - 100;
    matrixBlock(gs, CX, wY, 'W_d', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, MAT_W * 0.55, MAT_H * 0.45);
    arrowV(gs, CX, wY + MAT_H * 0.225, rowY - 16, COLORS.weight.stroke);

    const scaleNoteY = rowY + MAT_H * 0.4 + 20;
    scalarBlock(gs, CX + SIDE_OFF + 100, rowY, `1/(1-p)`, `${(1 / (1 - rate)).toFixed(2)}`, COLORS.scale.fill, COLORS.scale.stroke);

    shapeEq(gs, CX, scaleNoteY + SCALAR_SIZE / 2 + 28,
      `out = x @ W_d / (1-p)  [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, scaleNoteY + SCALAR_SIZE / 2 + 28 + 32,
      'scale by 1/(1-p) to preserve expectation', COLORS.scale.stroke);

    steps.push(makeStep(stepId, 'MatMul', 'Matrix Multiply',
      `out = x @ W_d`,
      'Multiply input by the masked weight matrix. Scale by 1/(1-p) for inverted dropout.',
      'step-matmul', COLORS.input.stroke, COLORS.input.fill,
      [`out = x @ W_dropped / (1 - ${rate})`]));
    y = scaleNoteY + SCALAR_SIZE / 2 + 28 + 32 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // Step 5: Output
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `out [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    matrixBlock(gs, CX, rowY, 'out', `[${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, MAT_W, MAT_H, String(dModel), String(seqLen));
    lbl(gs, CX + MAT_W / 2 + 24, rowY, 'E[out] = x @ W', { size: 11, color: COLORS.muted, anchor: 'start' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 32,
      `out [${seqLen}, ${dModel}]`, COLORS.output.stroke);
    sampleNote(gs, CX, rowY + MAT_H / 2 + 32 + 28,
      'more regularization than dropout — O(d²) mask', COLORS.weight.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `out [${seqLen}, ${dModel}]`,
      'DropConnect output has the same shape as standard linear layer output. The weight mask provides finer-grained regularization than activation dropout.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# DropConnect: mask weights, not activations`]));
    y = rowY + MAT_H / 2 + 32 + 28 + 22 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDropoutDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const dModel = Number(params.d_model) || 512;
  const rate = Number(params.rate) || 0.1;
  const variant = String(params.variant || 'standard') as DropoutVariant;
  const hiRow = 2;

  const stepsMeta: DropoutStep[] = [];
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Dropout', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  const variantLabel = variant === 'droppath' ? 'DropPath (Stochastic Depth)' : variant === 'dropconnect' ? 'DropConnect' : 'Standard Dropout';
  lbl(g, CX, y + 8,
    `${variantLabel} — regularization by random zeroing`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `seq_len: ${seqLen}`, `d_model: ${dModel}`, `rate: ${rate}`, `variant: ${variant.toUpperCase()}`,
  ]);
  y += 32;

  const { steps, y: finalY } = variant === 'droppath'
    ? renderDropPath(g, y, seqLen, dModel, rate, hiRow)
    : variant === 'dropconnect'
      ? renderDropConnect(g, y, seqLen, dModel, rate, hiRow)
      : renderStandard(g, y, seqLen, dModel, rate, hiRow);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += 32;
  const insightText = variant === 'droppath'
    ? 'DropPath (stochastic depth) drops entire residual branches instead of individual elements. Deeper blocks typically use higher drop rates (linearly increasing from 0 to ~0.2). Used extensively in Vision Transformers, ConvNeXt, and modern CNNs.'
    : variant === 'dropconnect'
      ? 'DropConnect masks individual weights instead of activations. This provides finer-grained regularization but requires an O(d²) mask per layer. The effective connectivity of the network is reduced during training.'
      : 'Standard dropout zeroes random activations and scales the rest by 1/(1-p) (inverted dropout) so the expected output matches the input. At inference time dropout is disabled — the full network is used.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Input shape [${seqLen}, ${dModel}]. No learned parameters (${(seqLen * dModel).toLocaleString()} elements per forward pass). Mask generation is O(${seqLen * dModel}).`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'softmax', 'Softmax');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'weight-init', 'Weight Init');
  y += 72;

  const codeTitle = `Dropout — ${variantLabel} (Python)`;
  const codeLines = variant === 'droppath'
    ? [`# DropPath (stochastic depth)`,
       `def drop_path(x, drop_rate=0.1, training=True):`,
       `    if not training or drop_rate == 0:`,
       `        return x`,
       `    keep = 1 - drop_rate`,
       `    shape = (x.shape[0],) + (1,) * (x.ndim - 1)`,
       `    mask = torch.bernoulli(torch.full(shape, keep))`,
       `    return x + mask * f(x) / keep`]
    : variant === 'dropconnect'
      ? [`# DropConnect (mask weights)`,
         `def drop_connect(x, W, p=0.1, training=True):`,
         `    if not training:`,
         `        return x @ W`,
         `    M = torch.bernoulli(torch.full_like(W, 1 - p))`,
         `    W_dropped = W * M`,
         `    return x @ W_dropped / (1 - p)`]
      : [`# Standard (inverted) dropout`,
         `def dropout(x, p=0.1, training=True):`,
         `    if not training:`,
         `        return x`,
         `    mask = torch.bernoulli(torch.full_like(x, 1 - p))`,
         `    return x * mask / (1 - p)`];

  drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160, codeTitle,
    [`${variantLabel} — x[${seqLen},${dModel}] → out[${seqLen},${dModel}]`], codeLines);

  return { width: W, height: y + 32, steps: stepsMeta };
}
